    ["破竹樽·紫心得散本奖励展示"] = "ƣƾểǃǦǉƽịǦǅƽầǃǦǉƽưởǃƼǦǉƁǂǦđắƸǦƫƽƑǦǥǇƕƸǦǥƇǃǦ·ǦƮƑƸƽǦǇờƾǦǉƓǂ",
    ["提升剑气造成的伤害"] = "ƢƾƶǦǉăǃƼǦǈƑǉǦǉƽươǃƼǦǤǄǦǀƾếǂǦǀƽƓǦƼƁǓǦǇƶ",
    ["该武器纹符存在重复词条，同时仅能生效一条，是否确认装备？"] = "ƱăǃǦǅƽƖǦǋũǦǀƽƓǦǃƐǓǦǉồǃǦǉạƾǦǉƽǊộƸǦǉƓǃƽǦǁặǅǦǁạƾ,ǦđồǃƼǦǉƽờƾǦƸƽỉǦƸƚǦǉƽểǦǅƽƑǉǦƽǊǓǦƽƾệǊǦǁựƸǦǂộǉǦǤƛǃƼ,ǦƸƚǦǍƑƸǦǃƽậǃǦǉǇƶǃƼǦƷịǦǀƽƇǃƼ?",
    ["武学技释放时，额外造成范围伤害并附加2层「冰裂」；解锁武器特有资源「剑意」，可通过释放武学技回复，攒满后轻击变体为旋斩，可释放4次。"] = "ƦƽƾǦǉƽƾǦǉǇƾểǃǦƸƽƾƙǊǦǉƽứƸǦǋƅǦƽọƸ,ǦƼƁǓǦǉƽƙǂǦǈƑǉǦǉƽươǃƼǦǤƾệǃǦǇộǃƼǦǋƐǦđƓǃƽǦǀƘǂǦ2ǦǉầǃƼǦ«ƝăǃƼǦƧƾệǉ»;ǦǂởǦǀƽƚƶǦǉƐƾǦǃƼǊǓƙǃǦđặƸǦǉǇưǃƼǦƸủƶǦǋũǦǀƽƓǦ«ƦƾếǂǦÝ»,ǦƸƚǦǉƽểǦƽồƾǦǅƽụƸǦǉƽƇǃƼǦǆǊƶǦǋƾệƸǦǉƽƾǦǉǇƾểǃǦƸƽƾƙǊǦǉƽứƸǦǋƅǦƽọƸ,ǦǀƽƾǦǉƓƸƽǦđầǓ,ǦđƛǃǦđƑǃƽǦǃƽẹǦƷƾếǃǦǉƽểǦǉƽƐǃƽǦƸƽƾƙǊǦǍǄƶǓǦǉǇảǂ,ǦƸƚǦǉƽểǦǉƽƾǦǉǇƾểǃǦ4Ǧǁầǃ.",
    ["普·41阶破竹樽"] = "ǥƽườǃƼǦ·ǦƫƽƑǦǥǇƕƸǦǥƇǃǦƷậƸǦ41",
    ["宝箱破竹·樽86级装备掉落金装"] = "ƭơƾǦǉǇƶǃƼǦƷịǦǋƐǃƼǦǉừǦǇươǃƼǦƫƽƑǦǥǇƕƸǦ·ǦǥƇǃǦƸấǅǦ86",
    ["满饮烈酒，进入#Y醉酒#E状态，可以通过#Y连续点击#E打出至多#Y5#E段攻击，每段攻击会消耗#Y6#E点精元值，期间获得#Y20%#E伤害减免与强韧效果；喝酒后#Y30#E秒内，释放#Y神龙吐火#E和#Y太白醉月#E将无需再次饮酒"] = "ǕốǃƼǦƸạǃǦǇượǊǦǂạǃƽ,ǦƷướƸǦǋƐǄǦǉǇạǃƼǦǉƽƑƾǦ#YǈƶǓǦǇượǊ#E,ǦƸƚǦǉƽểǦǉǊǃƼǦǇƶǦǉốƾǦđƶǦ#Y5#EǦđǄạǃǦǉấǃǦƸƇǃƼǦǉƽƇǃƼǦǆǊƶǦǋƾệƸǦ#ǓǃƽấǅǦǁƾƙǃǦǉụƸ#E,ǦǂỗƾǦđǄạǃǦǉấǃǦƸƇǃƼǦǈẽǦǉƾƙǊǦƽƶǄǦ#Y6#EǦđƾểǂǦǉƾǃƽǦǃƼǊǓƙǃ,ǦǉǇǄǃƼǦǉƽờƾǦƼƾƶǃǦđƚǦǃƽậǃǦ#Y20%#EǦƼƾảǂǦǈƑǉǦǉƽươǃƼǦǋƐǦƽƾệǊǦǆǊảǦƸườǃƼǦǃƽẫǃ;ǦǉǇǄǃƼǦǋƛǃƼǦ#Y30#EǦƼƾƁǓǦǈƶǊǦǀƽƾǦǊốǃƼǦǇượǊ,ǦǉƽƾǦǉǇƾểǃǦ#YǥƽầǃǦƧǄǃƼǦǥƽổǦƣỏƶ#EǦǋƐǦ#YǥƑƾǦƝạƸƽǦǥƕǓǦƩƼǊǓệǉ#EǦǈẽǦǀƽƇǃƼǦƸầǃǦǊốǃƼǦǇượǊǦǁạƾ",
    ["开启后可获得一本随机心法心得。\n推荐培养#Y破竹·樽#E流派心法的玩家选择，开启时概率获得#Y破竹·樽#E流派的#Y紫金品质心得#E、通用的全品质心得。"] = "ƮƶǊǦǀƽƾǦǂởǦƸƚǦǉƽểǦǃƽậǃǦǂộǉǦǆǊǓểǃǦǉƁǂǦǅƽƑǅǦǉƁǂǦđắƸǦǃƼẫǊǦǃƽƾƙǃ.\nƦƽǊǓƙǃǦǤƖǃƼǦƸƽǄǦǃƼườƾǦƸƽơƾǦđƶǃƼǦƷồƾǦǤưỡǃƼǦǉƁǂǦǅƽƑǅǦǁưǊǦǅƽƑƾǦ#YƫƽƑǦǥǇƕƸǦ·ǦǥƇǃ#EǦǁựƶǦƸƽọǃ,ǦǀƽƾǦǂởǦƸƚǦǉỷǦǁệǦǃƽậǃǦđượƸǦ#ǓǉƁǂǦđắƸǦǅƽẩǂǦƸƽấǉǦǉửǦǀƾǂ#EǦƸủƶǦǁưǊǦǅƽƑƾǦ#YƫƽƑǦǥǇƕƸǦ·ǦǥƇǃ#EǦǋƐǦǉƁǂǦđắƸǦǉǄƐǃǦǅƽẩǂǦƸƽấǉǦƸƽǊǃƼ.",
    ["100阶倾觞自选匣"] = "ƣộǅǦǉựǦƸƽọǃǦƦƽƾǃƽǦǥƽưởǃƼǦƷậƸǦ100",
    ["蓄力后发射巨大剑气，自身获得剑气伤害加成和必定会伤效果，同时召唤剑气随机攻击敌方。#ffc89c剑气、寒霜快斩造成的真气伤害提升20%#E"] = "ƮƶǊǦǀƽƾǦǉƓƸƽǦǁựƸǦǅƽƚǃƼǦǇƶǦǀƾếǂǦǀƽƓǦǀƽổǃƼǦǁồ,ǦƷảǃǦǉƽƁǃǦǃƽậǃǦƼƾƶǦǉăǃƼǦǈƑǉǦǉƽươǃƼǦǀƾếǂǦǀƽƓǦǋƐǦƽƾệǊǦǆǊảǦƸƽắƸǦƸƽắǃǦƷạǄǦǉƽươǃƼ,ǦđồǃƼǦǉƽờƾǦǉǇƾệǊǦƽồƾǦǀƾếǂǦǀƽƓǦǉấǃǦƸƇǃƼǦǃƼẫǊǦǃƽƾƙǃǦǀẻǦđịƸƽ.Ǧ#ffc89cƮƑǉǦǉƽươǃƼǦƸƽƁǃǦǀƽƓǦǤǄǦǀƾếǂǦǀƽƓǦǋƐǦƸƽƗǂǦǃƽƶǃƽǦǈươǃƼǦǁạǃƽǦƼƁǓǦǇƶǦǉăǃƼǦ20%#E",
    ["完成剧情「医心为安」"] = "ƣǄƐǃǦǉƽƐǃƽǦƸốǉǦǉǇǊǓệǃǦ«ƴǦǥƁǂǦƱƾǦƜǃ»",
    ["队伍状态"] = "ǥǇạǃƼǦǉƽƑƾǦđộƾǦǃƼũ",
    ["#Y醉饮#E状态期间，自身受到的直接伤害降低5%，受到的持续伤害提升10%。\n#Y醉饮#E状态包括：<酩酊状态|781|#C|20902|20902006>、醉酒状态（使用奇术获得）"] = "ǥǇǄǃƼǦǉƽờƾǦƼƾƶǃǦǉǇạǃƼǦǉƽƑƾǦ#YǈƶǓǦǈưƶ#E,ǦǈƑǉǦǉƽươǃƼǦǉǇựƸǦǉƾếǅǦƷảǃǦǉƽƁǃǦǅƽảƾǦƸƽịǊǦƼƾảǂǦ5%,ǦǈƑǉǦǉƽươǃƼǦǤǊǓǦǉǇƔǦǅƽảƾǦƸƽịǊǦǉăǃƼǦ10%.\nǥǇạǃƼǦǉƽƑƾǦ#YǈƶǓǦǈưƶ#EǦƷƶǄǦƼồǂ:Ǧ<ǉǇạǃƼǦǉƽƑƾǦǈƶǓǦǂƘǂ|781|#C|20902|20902006>,ǦǉǇạǃƼǦǉƽƑƾǦǈƶǓǦǇượǊǦ(ǃƽậǃǦđượƸǦǀƽƾǦǈửǦǤụǃƼǦǀỳǦǉƽǊậǉ)",
    ["新流派"] = "ƧưǊǦǅƽƑƾǦǂớƾ",
    ["当前无可用道具"] = "ƣƾệǃǦǀƽƇǃƼǦƸƚǦđạǄǦƸụǦǀƽảǦǤụǃƼ",
    ["大郎君求人办事，还是这么“直率”啊？"] = "ĐạƾǦǁƶǃƼǦǆǊƁǃǦƸầǊǦǍƾǃǦǃƼườƾǦǀƽƑƸǦǁƐǂǦǋƾệƸ,ǦǋẫǃǦ«ǉǇựƸǦǉƓǃƽ»ǦǃƽưǦǋậǓǦǈƶǄ?",
    ["多人肉鸽-首通奖励-新手关"] = "ƭǄƼǊƺǁƾǀƺǦǃƽƾềǊǦǃƼườƾǦ-ǦǥƽưởǃƼǦǋượǉǦảƾǦǁầǃǦđầǊǦ-ǦƨƐǃǦǉƁǃǦǉƽủ",
    ["同时命中不少于2个敌人或命中首领时，获得增益：武学技造成伤害提升#Y2.24%#E，会伤提升#Y1.68%#E，持续#Y3#E秒，再次达成刷新持续时间。"] = "ƦƽƾǦđồǃƼǦǉƽờƾǦđƑǃƽǦǉǇƕǃƼǦǉừǦ2ǦǀẻǦđịƸƽǦǉǇởǦǁƙǃǦƽǄặƸǦđƑǃƽǦǉǇƕǃƼǦǉƽủǦǁĩǃƽ,ǦǃƽậǃǦđượƸǦƷǊƻƻ:ǦǈƑǉǦǉƽươǃƼǦǤǄǦƸƽƾƙǊǦǉƽứƸǦǋƅǦƽọƸǦƼƁǓǦǇƶǦǉăǃƼǦ#Y2.24%#E,ǦƷạǄǦǉƽươǃƼǦǉăǃƼǦ#Y1.68%#E,ǦǤǊǓǦǉǇƔǦ#Y3#EǦƼƾƁǓ,ǦđạǉǦǁạƾǦǈẽǦǁƐǂǦǂớƾǦǉƽờƾǦƼƾƶǃǦǤǊǓǦǉǇƔ.",
    ["封丘村台上的比武招亲，不是为了什么鸳鸯侠侣、武林恩怨，只为了一个字——钱。"] = "ƧƇƾǦđƐƾǦǉỉǦǉƽƓǦǀƗǃǦǇểǦǉǇƙǃǦđƐƾǦởǦǉƽƇǃǦƫƽǄǃƼǦƦƽƁǊ,ǦǀƽƇǃƼǦǅƽảƾǦǋƔǦǊǓƙǃǦươǃƼǦƽƾệǅǦǁữǦƼƔ,ǦƸũǃƼǦƸƽẳǃƼǦǋƔǦƁǃǦǄƑǃǦǋƅǦǁƁǂ,ǦǂƐǦƸƽỉǦǋƔǦǂộǉǦƸƽữǦ——Ǧǥƾềǃ.",
    ["#ddd4e2天地一盏尽樽华"] = "#ddd4e2ǥƽƾƙǃǦĐịƶǦƩƽấǉǦǥǇảǃǦǥậǃǦǥƇǃǦƣǄƶ",
    ["刚在染坊做的夹缬方帕。拿去吧，你的七夕礼物。这下不用跳西湖了吧？"] = "ƦƽăǃǦǉƶǓǦƼƾƑǅ缬ǦǋừƶǦǁƐǂǦởǦǍưởǃƼǦǃƽǊộǂǦǍǄǃƼ.ǦƞầǂǦǁấǓǦđƾ,ǦǆǊƐǦǥƽấǉǦǥịƸƽǦƸủƶǦǃƼươƾǦđấǓ.ǦƧầǃǦǃƐǓǦǀƽƇǃƼǦƸầǃǦǅƽảƾǦǃƽảǓǦǍǊốǃƼǦǥƁǓǦƣồǦǃữƶǦƸƽứ?",
    ["调息：80秒。\n狂饮一口酒，立即进入酩酊·浓醺状态，并额外获得13秒酩酊·杯合状态。酩酊·杯合期间免疫奇术造成的沉默效果，并减免2米外伤害来源造成的伤害，距离每超过2米减少10%，最多减少80%。"] = "ĐƾềǊǦǉứƸ:Ǧ80ǦƼƾƁǓ.\nǕốǃƼǦựƸǦǂộǉǦǃƼụǂǦǇượǊ,ǦǁậǅǦǉứƸǦƷướƸǦǋƐǄǦǉǇạǃƼǦǉƽƑƾǦǈƶǓǦǂƘǂ·ǈƶǓǦđậǂ,ǦđồǃƼǦǉƽờƾǦǃƽậǃǦǉƽƙǂǦ13ǦƼƾƁǓǦǉǇạǃƼǦǉƽƑƾǦǈƶǓǦǂƘǂ·ƷƇƾǦƽợǅ.ǦǥǇǄǃƼǦǉƽờƾǦƼƾƶǃǦǈƶǓǦǂƘǂ·ƷƇƾǦƽợǅ,ǦǂƾễǃǦǃƽƾễǂǦƽƾệǊǦǆǊảǦƸƁǂǦǁặǃƼǦǤǄǦǀỳǦǉƽǊậǉǦƼƁǓǦǇƶ,ǦđồǃƼǦǉƽờƾǦƼƾảǂǦǈƑǉǦǉƽươǃƼǦǉừǦǃƼǊồǃǦǈƑǉǦǉƽươǃƼǦƸƑƸƽǦǍƶǦǃƼǄƐƾǦ2ǦǂƗǉ,ǦƸứǦƸƑƸƽǦǂỗƾǦ2ǦǂƗǉǦƼƾảǂǦ10%,ǦƼƾảǂǦǉốƾǦđƶǦ80%.",
    ["叶龙·绝境"] = "ǝƾệǅǦƧǄǃƼǦ·ǦǥǊǓệǉǦƞảǃƽ",
    ["105阶破竹樽"] = "ƫƽƑǦǥǇƕƸǦǥƇǃǦƷậƸǦ105",
    ["请求发送成功!"] = "ƢửƾǦǓƙǊǦƸầǊǦǉƽƐǃƽǦƸƇǃƼ!",
    ["武学技造成伤害提升#Y7.2%#E，会伤提升#Y5.4%#E，持续#Y3#E秒。"] = "ƮƑǉǦǉƽươǃƼǦǤǄǦƸƽƾƙǊǦǉƽứƸǦǋƅǦƽọƸǦƼƁǓǦǇƶǦǉăǃƼǦ#Y7.2%#E,ǦƷạǄǦǉƽươǃƼǦǉăǃƼǦ#Y5.4%#E,ǦǤǊǓǦǉǇƔǦ#Y3#EǦƼƾƁǓ.",
    ["寒刃·亡语"] = "ƣƐǃǦƩƽậǃǦ·ǦƱǄǃƼǦƩƼữ",
    ["蓄力后发射巨大剑气造成高额伤害，而后获得15秒强化效果：剑气伤害增加且必定会伤，同时召唤剑气随机攻击敌方。技能释放期间获得免伤和霸体效果。#ffc89c剑气、寒霜快斩造成的真气伤害提升20%#E"] = "ƮƶǊǦǀƽƾǦǉƓƸƽǦǁựƸǦǅƽƚǃƼǦǇƶǦǀƾếǂǦǀƽƓǦǀƽổǃƼǦǁồǦƼƁǓǦǈƑǉǦǉƽươǃƼǦǁớǃ,ǦǈƶǊǦđƚǦǃƽậǃǦ15ǦƼƾƁǓǦƽƾệǊǦǆǊảǦƸườǃƼǦƽƚƶ:ǦǈƑǉǦǉƽươǃƼǦǀƾếǂǦǀƽƓǦǉăǃƼǦǋƐǦƸƽắƸǦƸƽắǃǦƷạǄǦǉƽươǃƼ,ǦđồǃƼǦǉƽờƾǦǉǇƾệǊǦƽồƾǦǀƾếǂǦǀƽƓǦǉấǃǦƸƇǃƼǦǃƼẫǊǦǃƽƾƙǃǦǀẻǦđịƸƽ.ǦǥǇǄǃƼǦǉƽờƾǦƼƾƶǃǦǉƽƾǦǉǇƾểǃǦǀỹǦǃăǃƼǦǃƽậǃǦđượƸǦƽƾệǊǦǆǊảǦǂƾễǃǦǉƽươǃƼǦǋƐǦƷƑǦǉƽể.Ǧ#ffc89cƮƑǉǦǉƽươǃƼǦƸƽƁǃǦǀƽƓǦǤǄǦǀƾếǂǦǀƽƓǦǋƐǦƸƽƗǂǦǃƽƶǃƽǦǈươǃƼǦǁạǃƽǦƼƁǓǦǇƶǦǉăǃƼǦ20%#E",
